dslRule:
"Warn about usage of deprecated Platform.ARCH_X86 constant":
org.eclipse.core.runtime.Platform.ARCH_X86
;;

beforeExample:
package test;

import org.eclipse.core.runtime.Platform;

public class Example {
    public void checkArchitecture() {
        String currentArch = Platform.ARCH_X86;
        System.out.println("Running on " + currentArch);
    }
}

afterExample:
package test;

import org.eclipse.core.runtime.Platform;

public class Example {
    public void checkArchitecture() {
        String currentArch = Platform.ARCH_X86; // This line would display a warning.
        System.out.println("Running on " + currentArch);
    }
}

negativeExample:
package test;

import org.eclipse.core.runtime.Platform;

public class Example {
    public void checkArchitecture() {
        String currentArch = Platform.ARCH_X86_64;
        System.out.println("Running on " + currentArch);
    }
}
